const FILE: &str = "<svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><circle cx=\"12\" cy=\"14\" r=\"1\" fill=\"currentColor\" stroke=\"none\"/></svg>";

/// The icon for a shortcut called `name` of kind `kind` (`file`, `folder`, `app`, `url`).
pub fn icon_for(name: &str, kind: &str) -> &'static str {
    let key = name.trim().to_lowercase();
    NAMED.iter().find(|(n, _)| *n == key)
        .or_else(|| BY_TYPE.iter().find(|(t, _)| *t == kind))
        .map_or(FILE, |(_, svg)| svg)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_then_kinds_then_a_file() {
        assert_eq!(icon_for(" ChatGPT ", "app"), NAMED.iter().find(|(n, _)| *n == "chatgpt").unwrap().1);
        assert_eq!(icon_for("Мои документы", "folder"), BY_TYPE.iter().find(|(t, _)| *t == "folder").unwrap().1);
        assert_eq!(icon_for("notes.txt", "file"), FILE);
        assert!(NAMED.len() > 20 && NAMED.iter().all(|(_, svg)| svg.starts_with("<svg ") && svg.ends_with("</svg>")));
    }
}
